-- Наполнение FAQ вопросом про новый редактор .dat-файлов в разделе «Патчи» (30 июля)
INSERT INTO faq_items (question, answer, sort_order) VALUES
('Как редактировать игровые .dat-файлы прямо в разделе «Патчи»?', '<p>Для текстовых <strong>.dat</strong>-файлов клиента (там, где хранятся названия и описания предметов, скиллов, нпс, квестов, брони, оружия и других данных — свыше 80 файлов) в разделе «Патчи» появился встроенный редактор — сторонний софт для этого больше не нужен.</p>
<p>Откройте нужный файл в дереве (например <strong>System/itemname-e.dat</strong>) — рядом появится иконка редактирования. Доступные возможности:</p>
<ul>
<li><strong>Поиск</strong> записи по названию/описанию или по точному ID (<code>id=123</code>)</li>
<li><strong>Просмотр диапазона</strong> записей по ID одной таблицей с редактированием прямо в ячейках</li>
<li><strong>Создание</strong> одной новой записи или списком (можно вставить сразу несколько строк, например из Excel)</li>
<li><strong>Дублирование</strong> и <strong>удаление</strong> существующей записи</li>
<li>Для файлов со сложной структурой (списки моделей/текстур, материалы рецептов и т.п.) — редактирование записи целиком одной строкой с подписанными колонками</li>
</ul>
<p>Порядок записей по ID поддерживается автоматически при создании и редактировании — новая или изменённая запись сама встаёт на своё место, а не в конец файла. Есть защита от случайного создания записи с уже существующим ID.</p>
<p>Функция работает одинаково для серверов <strong>С4х1</strong> и <strong>HFx3 old / HF new</strong>, включая самые сложные файлы вроде <strong>armorgrp.dat</strong>, <strong>weapongrp.dat</strong> и <strong>npcgrp.dat</strong>.</p>
<p>Искать и просматривать записи может любой авторизованный участник. Создавать, редактировать, удалять и дублировать записи могут только администраторы и участники с правом полного редактирования задач.</p>', 32),
('Что за подсказки с описанием файлов в дереве «Патчей»?', '<p>Рядом с каждым файлом и папкой в дереве «Патчей» появилась маленькая иконка ⓘ — при наведении показывает подсказку, для чего этот файл или папка нужны в игровом клиенте (например <strong>itemname-e.dat</strong> → «Имена и описания предметов»). Справочник встроен и покрывает более 80 файлов и все стандартные папки.</p>
<p>Руководитель проекта дополнительно может отредактировать или добавить своё описание прямо в этой подсказке — оно сохранится и будет видно всем участникам. У остальных администраторов кнопки редактирования нет, они видят только готовый текст.</p>', 33);